const warnAt = Number(params.warnAt ?? 80);
const critAt = Number(params.critAt ?? 90);
return items.map(i => {
  const pct = Number(i.json.disk_root_pct ?? 0);
  const grade = pct >= critAt ? "critical" : pct >= warnAt ? "warning" : "ok";
  const message = grade === "ok" ? "Disk usage normal" : `Disk usage ${grade}: ${pct}%`;
  return { json: { ...i.json, grade, message } };
});
